-- ------------------------------------------------------------
-- 2) 存量模板/任务快照回填：按 material_id 关联 material.image_url
--    （collation 不一致，JOIN 显式 COLLATE 防 1267）
-- ------------------------------------------------------------

UPDATE template_zone_material tzm
JOIN material m ON m.material_id = tzm.material_id COLLATE utf8mb4_unicode_ci
SET tzm.image_url = m.image_url
WHERE tzm.del_flag = 0 AND m.del_flag = 0 AND m.image_url IS NOT NULL;

UPDATE task_zone_material tzm
JOIN material m ON m.material_id = tzm.material_id COLLATE utf8mb4_unicode_ci
SET tzm.image_url = m.image_url
WHERE tzm.del_flag = 0 AND m.del_flag = 0 AND m.image_url IS NOT NULL;

-- 核对：快照表有图行数（模板/任务）：SELECT COUNT(*) FROM template_zone_material WHERE del_flag=0 AND image_url IS NOT NULL;
--       SELECT COUNT(*) FROM task_zone_material WHERE del_flag=0 AND image_url IS NOT NULL;

-- 3) 存量汇总表回填（提交过的任务汇总）

UPDATE task_material_summary sm
JOIN material m ON m.material_id = sm.material_id COLLATE utf8mb4_unicode_ci
SET sm.image_url = m.image_url
WHERE sm.del_flag = 0 AND m.del_flag = 0 AND m.image_url IS NOT NULL;

-- 核对汇总表：SELECT COUNT(*) FROM task_material_summary WHERE del_flag=0 AND image_url IS NOT NULL;
